"""Lets the Android project generated by `tauri android init` sign release builds
with the keystore described in src-tauri/gen/android/keystore.properties
(written by the release workflow from repository secrets). Run after init."""
import pathlib
import sys

gradle = pathlib.Path('src-tauri/gen/android/app/build.gradle.kts')
text = gradle.read_text()
if 'signingConfigs' in text:
    sys.exit(0)  # already patched

# Inside android {} the name `java` resolves to the Android extension (AGP 9),
# so fully qualified java.util/java.io names do not compile there; import them.
for name in ('java.util.Properties', 'java.io.FileInputStream'):
    if f'import {name}\n' not in text:
        text = f'import {name}\n' + text

signing = '''android {
    signingConfigs {
        create("release") {
            val props = Properties()
            val keystoreProperties = rootProject.file("keystore.properties")
            if (keystoreProperties.exists()) FileInputStream(keystoreProperties).use { props.load(it) }
            keyAlias = props["keyAlias"] as String
            keyPassword = props["password"] as String
            storeFile = file(props["storeFile"] as String)
            storePassword = props["password"] as String
        }
    }'''
if 'android {' not in text or 'getByName("release") {' not in text:
    sys.exit('unexpected build.gradle.kts layout: ' + str(gradle))
text = text.replace('android {', signing, 1)
text = text.replace('getByName("release") {', 'getByName("release") {\n            signingConfig = signingConfigs.getByName("release")', 1)
gradle.write_text(text)
print('release signing configured')
